<?php
declare(strict_types=1);
return [
    "CREATE TABLE finance_wallet_conversions (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,wallet_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,source_currency CHAR(3) CHARACTER SET ascii NOT NULL,target_currency CHAR(3) CHARACTER SET ascii NOT NULL,original_minor BIGINT NOT NULL CHECK(original_minor>=0),converted_minor BIGINT NOT NULL CHECK(converted_minor>=0),fx_snapshot_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,source_journal_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,target_journal_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,actor_id VARCHAR(64) CHARACTER SET ascii NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),FOREIGN KEY(wallet_id) REFERENCES finance_wallets(id),FOREIGN KEY(fx_snapshot_id) REFERENCES finance_fx_snapshots(id),FOREIGN KEY(source_journal_id) REFERENCES finance_journals(id),FOREIGN KEY(target_journal_id) REFERENCES finance_journals(id)) ENGINE=InnoDB",
    "ALTER TABLE finance_wallets ADD last_conversion_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,ADD FOREIGN KEY(last_conversion_id) REFERENCES finance_wallet_conversions(id)",
    "CREATE TABLE finance_wallet_conversion_applications (conversion_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,wallet_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),FOREIGN KEY(conversion_id) REFERENCES finance_wallet_conversions(id),FOREIGN KEY(wallet_id) REFERENCES finance_wallets(id)) ENGINE=InnoDB",
    "DROP TRIGGER finance_wallets_update",
    "CREATE TRIGGER finance_wallets_update BEFORE UPDATE ON finance_wallets FOR EACH ROW BEGIN IF NEW.id<>OLD.id OR NEW.customer_id<>OLD.customer_id OR NEW.created_at<>OLD.created_at OR NEW.currency=OLD.currency OR NEW.last_conversion_id IS NULL OR NEW.last_conversion_id<=>OLD.last_conversion_id OR NOT EXISTS(SELECT 1 FROM finance_wallet_conversions c WHERE c.id=NEW.last_conversion_id AND c.wallet_id=OLD.id AND c.source_currency=OLD.currency AND c.target_currency=NEW.currency AND c.converted_minor=(SELECT COALESCE(SUM(e.amount_minor),0) FROM finance_wallet_entries e JOIN finance_journals j ON j.id=e.journal_id WHERE e.wallet_id=OLD.id AND j.currency=NEW.currency)) OR (SELECT COALESCE(SUM(e.amount_minor),0) FROM finance_wallet_entries e JOIN finance_journals j ON j.id=e.journal_id WHERE e.wallet_id=OLD.id AND j.currency=OLD.currency)<>0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Wallet currency conversion evidence required'; END IF; INSERT INTO finance_wallet_conversion_applications(conversion_id,wallet_id) VALUES (NEW.last_conversion_id,OLD.id); END",
    "CREATE TRIGGER wallet_conversions_update BEFORE UPDATE ON finance_wallet_conversions FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Immutable wallet conversion'",
    "CREATE TRIGGER wallet_conversions_delete BEFORE DELETE ON finance_wallet_conversions FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Immutable wallet conversion'",
    "CREATE TRIGGER wallet_conversion_applications_update BEFORE UPDATE ON finance_wallet_conversion_applications FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Immutable wallet conversion application'",
    "CREATE TRIGGER wallet_conversion_applications_delete BEFORE DELETE ON finance_wallet_conversion_applications FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Immutable wallet conversion application'",
];
